root=Path(r'D:\EIS-DOCS\docs\manual-production')
path=root/'EIS-DOCS_Production_User_Manual_TH.docx'
shutil.copy2(path,root/'qa'/'manual-before-ui-20261009.docx')
d=Document(path)
def replace_chapter(prefix,title,items):
 heading=next(p for p in d.paragraphs if p.style.name=='Heading 1' and p.text.startswith(prefix))
 headings=[p for p in d.paragraphs if p.style.name=='Heading 1']
 index=next(i for i,p in enumerate(headings) if p._p is heading._p)
 following=headings[index+1] if index+1<len(headings) else None
 boundary=following._p.getprevious() if following is not None else d.element.body[-1]
 if following is not None and not boundary.xpath('.//w:br[@w:type="page"]'):boundary=following._p
 node=heading._p.getnext()
 while node is not boundary:
  nxt=node.getnext();node.getparent().remove(node);node=nxt
 heading.text=title
 for style,t in items:
  p=d.add_paragraph(t,style=style);boundary.addprevious(p._p)
def body(t):return ('Normal',t)
def sub(t):return ('Heading 2',t)

